const byId = new Map(HELP_TOPICS.map(value => [value.id, value]));
const groupTopic = {
  engines: 'engines', performance: 'velocity', chords: 'play-chords', arps: 'arps',
  sequencer: 'sequencer-tracks', midi: 'midi-routing', expression: 'mpe',
  sensitivity: 'sensitivity', views: 'views', lights: 'lights', controls: 'controls',
  storage: 'storage', system: 'system',
};
const exact = {
  play: 'play-chords', tracks: 'sequencer-tracks', steps: 'sequencer-editor',
  'track-settings': 'track-settings', 'sequencer': 'sequencer-tracks',
  'performance.mpe': 'mpe', 'performance.routeTarget': 'aftertouch',
  'performance.pressureMode': 'aftertouch', 'performance.pressureBend': 'aftertouch',
  'performance.bendRange': 'aftertouch', 'sensitivity.velocityMode': 'velocity',
  'sensitivity.calibrate': 'calibration', 'system.storage': 'storage',
  'storage.exportProfile': 'backup', 'storage.importProfile': 'backup',
  'sequencer.help': 'sequencer-editor', 'sequencer.source': 'sequencer-recording',
};
const menuById = new Map(MENU_ROWS.map(value => [value.id, value]));

export function resolveHelpTopic(context = 'getting-started') {
  const id = String(context || 'getting-started');
  if (Object.hasOwn(exact, id)) return exact[id];
  if (byId.has(id)) return id;
  if (/^(chords\.(edit|userScale|sixBank)|storage\.user)/.test(id)) return 'custom-library';
  if (/^sensitivity\.(profile|pressureCurve|aftertouchCurve)/.test(id)) return 'aftertouch';
  if (/^sensitivity\.(velocity|softSpeed|hardSpeed|minVelocity|maxVelocity)/.test(id)) return 'velocity';
  if (/^midi\.(pressure|bend)/.test(id)) return 'aftertouch';
  if (/^sequencer\.(channel|destinations|length|grid|input|loop|region|stepLength)/.test(id)) return 'track-settings';
  const row = menuById.get(id);
  const group = row?.group || id.split('.')[0];
  return Object.hasOwn(groupTopic, group) ? groupTopic[group] : 'getting-started';
}

export function getHelpTopic(context) { return byId.get(resolveHelpTopic(context)); }

function cleanDescription(text = '') { return String(text); }

export function getHelpContext(context) {
  const article = getHelpTopic(context), row = menuById.get(String(context));
  return {
    topic: article,
    title: row ? row.label : article.title,
    summary: row ? cleanDescription(row.description) : article.summary,
    options: row?.type === 'select' ? (row.options || []).map(option => option.label) : [],
    unavailable: Boolean(row && row.status !== 'live'),
  };
}

export function getHelpReference(id) {
  const topicId = resolveHelpTopic(id);
  return MENU_ROWS.filter(row => row.status === 'live' && !row.retired &&
    resolveHelpTopic(row.id) === topicId).map(row => ({
      id: row.id, title: row.label, description: cleanDescription(row.description),
      choices: row.type === 'select' ? (row.options || []).map(option => option.label) :
        row.type === 'toggle' ? ['Off', 'On'] :
        row.type === 'number' ? [`${row.min}–${row.max}${row.unit ? ` ${row.unit}` : ''}`] : [],
    }));
}

const normalized = value => String(value || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
export function searchHelpTopics(query = '') {
  const words = normalized(query).trim().split(/\s+/).filter(Boolean);
  if (!words.length) return [...HELP_TOPICS];
  return HELP_TOPICS.map((item, order) => {
    const title = normalized(item.title), tags = normalized(item.keywords.join(' '));
    const reference = getHelpReference(item.id);
    // Search the guidance and captions, not SVG geometry or encoded image data.
    const sections = item.sections.map(({ figures, ...part }) => ({ ...part,
      figures: figures?.map(({ label, alt, caption }) => ({ label, alt, caption })) }));
    const body = normalized(JSON.stringify([item.summary, sections, reference]));
    if (!words.every(word => title.includes(word) || tags.includes(word) || body.includes(word))) return null;
    const score = words.reduce((sum, word) => sum + (title.includes(word) ? 5 : 0) + (tags.includes(word) ? 3 : 0), 0);
    return { item, score, order };
  }).filter(Boolean).sort((a, b) => b.score - a.score || a.order - b.order).map(result => result.item);
}
